#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
INSTALADOR - Ampliacion del juego "Domina Fines y Criterios"
============================================================
Agrega al juego (ruta /fines-y-criterios, clave 1111):
  + Objetivos de la NEM   (Art. 11 LGE) - 4 objetivos
  + Desarrollo Humano Integral / DHI (Art. 12 LGE) - 5 propositos
  + Modo NUEVO "Derechos y Obligaciones" (Art. 128 y 129 LGE):
      arriba la palabra clave, abajo dos botones: Derecho / Obligacion
  (Los Fines Art. 15 y Criterios Art. 16 se conservan tal cual)

Actualiza 2 archivos:
  src/data/juego-fines-criterios.js
  src/components/JuegoFinesCriterios.js

Seguro: respaldo automatico, idempotente (se puede correr de nuevo).
Ejecutar desde la raiz del proyecto:
    cd ~/Desktop/sindicato-sesion1
    python3 instalar_juego_ampliado.py
"""
import os, sys, base64, json, shutil
from datetime import datetime

PAYLOAD_B64 = ""

ROOT = os.getcwd()
TS = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP_DIR = os.path.join(ROOT, "_backups_juego_ampliado_" + TS)

DATA_OUT = os.path.join(ROOT, "src", "data", "juego-fines-criterios.js")
COMP_OUT = os.path.join(ROOT, "src", "components", "JuegoFinesCriterios.js")

def die(m):
    print("\n[ERROR] " + m); sys.exit(1)

def backup(p):
    if os.path.isfile(p):
        rel = os.path.relpath(p, ROOT)
        dst = os.path.join(BACKUP_DIR, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(p, dst); return True
    return False

def write_file(p, content):
    existed = backup(p)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "w", encoding="utf-8") as f:
        f.write(content)
    rel = os.path.relpath(p, ROOT)
    print(("   [~] actualizado " if existed else "   [+] creado     ") + rel)

def main():
    print("=" * 60)
    print("  AMPLIACION - Domina Fines y Criterios")
    print("  + Art. 11 (Objetivos NEM) + Art. 12 (DHI) + Derechos/Obligaciones")
    print("=" * 60)

    if not os.path.isdir(os.path.join(ROOT, "src", "data")) or not os.path.isdir(os.path.join(ROOT, "src", "components")):
        die("No parece la raiz de sindicato-sesion1.\n"
            "   Entra a la carpeta:  cd ~/Desktop/sindicato-sesion1\n"
            "   (debe existir src/data/ y src/components/)")

    if not os.path.isfile(COMP_OUT):
        print("   [!] Aviso: no existia src/components/JuegoFinesCriterios.js; se creara nuevo.")

    data = json.loads(base64.b64decode(PAYLOAD_B64).decode())
    data_js = base64.b64decode(data["data_b64"]).decode()
    comp_js = base64.b64decode(data["comp_b64"]).decode()

    print("\nProyecto: " + ROOT)
    print("Backups : " + os.path.relpath(BACKUP_DIR, ROOT) + "/  (solo si algo existia)\n")
    print("Escribiendo archivos:")
    write_file(DATA_OUT, data_js)
    write_file(COMP_OUT, comp_js)

    print("\n" + "=" * 60)
    print("LISTO. El juego ahora tiene 3 modos (clave 1111):")
    print("   1) Entrenamiento  -> Fines, Criterios, Objetivos NEM y DHI (26 rondas)")
    print("   2) Caza al Impostor -> con los 4 tipos")
    print("   3) Derechos y Obligaciones -> clasificar Derecho/Obligacion (15 tarjetas)")
    print("   Ruta: /fines-y-criterios")
    print("\nVerifica y publica:")
    print("   npm run build")
    print("   git add src/data/juego-fines-criterios.js src/components/JuegoFinesCriterios.js")
    print('   git commit -m "Juego: + Art.11 Objetivos NEM, Art.12 DHI y modo Derechos/Obligaciones"')
    print("   git push")
    print("=" * 60)

if __name__ == "__main__":
    main()
